const supportAdvanceTotals = `-- name: SupportAdvanceTotals :one
SELECT COALESCE(sum(a.amount_yen), 0)::int AS total_yen,
       COALESCE(sum(a.amount_yen) FILTER (WHERE e.payout_id IS NOT NULL), 0)::int AS paid_yen
FROM support_coach_advances a JOIN coach_earnings e ON e.id = a.earning_id
WHERE a.contract_id = $1
`

type SupportAdvanceTotalsRow struct {
	TotalYen int32 `json:"total_yen"`
	PaidYen  int32 `json:"paid_yen"`
}

// 仮払いの合計（送金に含めた分と、まだの分）。
func (q *Queries) SupportAdvanceTotals(ctx context.Context, contractID uuid.UUID) (SupportAdvanceTotalsRow, error) {
	row := q.db.QueryRow(ctx, supportAdvanceTotals, contractID)
	var i SupportAdvanceTotalsRow
	err := row.Scan(&i.TotalYen, &i.PaidYen)
	return i, err
}
